import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import {
  resultCodeConsentsActionResultCodeSchema,
  type ResultCodeConsentsActionResultCode,
} from "./result-code-consents-action-result-code.js";
import { typeConsentsActionTypeSchema, type TypeConsentsActionType } from "./type-consents-action-type.js";

export type Action20 = {
  /** A unique identifier generated by Global Payments to identify an action. */
  id?: string;
  /** Indicates the specific action taken. */
  type?: TypeConsentsActionType;
  /** Global Payments time indicating when the object was created in ISO-8601 format. */
  timeCreated?: Date;
  /** The result of the action executed. SUCCESS - indicates the action executed successfully. */
  resultCode?: ResultCodeConsentsActionResultCode;
  /** The id of the app that was used to create the access token. */
  appId?: string;
  /** The name of the app the user gave to the application. */
  appName?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

const action20Properties: s.Shape<Action20> = {
  id: s.optional(s.string()),
  type: s.optional(s.lazy(() => typeConsentsActionTypeSchema)),
  timeCreated: s.optional(s.dateTime()),
  resultCode: s.optional(s.lazy(() => resultCodeConsentsActionResultCodeSchema)),
  appId: s.optional(s.string()),
  appName: s.optional(s.string()),
  _keysMap: {
    timeCreated: "time_created",
    resultCode: "result_code",
    appId: "app_id",
    appName: "app_name",
  },
};

export const action20InternalSchema: Schema<Action20> = s.object<Action20>(action20Properties, {
  additionalProperties: s.json(),
});

export const action20Schema: Schema<Action20> = s.lazySchema(() =>
  s.object<Action20>(
    {
      ...action20Properties,
      id: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      appId: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
    },
    { additionalProperties: s.json() },
  ),
);
